UPDATE books SET summary = 'Percy, Annabeth y Tyson (un cíclope, medio hermano de Percy) navegan el Mar de los Monstruos en busca del Vellocino de Oro para salvar el Campamento Mestizo, mientras Luke —ahora aliado del titán Cronos— trama su resurrección.' WHERE id = 13;
